@startuml

abstract class Contract {
  + {abstract} getCharges() : double
  + {abstract} getBalance() : double
  + {abstract} setBalance(double) : void
}

class BasicContract extends Contract {
  + contractNumber : int
  + balance : double
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

abstract class ContractDecorator extends Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class DataOption extends ContractDecorator {
  + monthlyCharge : double
}

class SmsOption extends ContractDecorator {
  + monthlyCharge : double
}

class MinutesOption extends ContractDecorator {
  + monthlyCharge : double
}

class DoubleTransferRateOption extends ContractDecorator {
  + monthlyCharge : double
}

Contract "1" *-- "0..*" ContractDecorator : decorated by
ContractDecorator "1" --> "1" Contract : decorates

@enduml

